// === Tab: Heart ===
function drawHeart(hx, hy, w, h, a, b, c, r, lines, flip, lips) {
	push();
	stroke(lips);
	strokeWeight(h / 8);
	if (lines) noFill();
	else fill(c);
	let num = floor(random(18, 30));
	beginShape();
	curveVertex(hx, hy);

	for (let t = 0; t < TWO_PI; t += (Math.max(0.001, Math.abs(TWO_PI / num)) || 1)) {
		let x = (w * Math.pow(sin(t), 3));
		let y = flip * (h * cos(t) - (h / 3) * cos(2 * t) - 2 * cos(a * t) - cos(b * t));
		curveVertex(hx + x, hy + y);
		if (lines) {
			stroke(0);
			line(hx, hy, hx + x, hy + y);
		}
	}
	curveVertex(hx, hy);
	endShape();
	pop();
}

// === Tab: Tooth ===
function drawTooth(x, y, s, c, row) {
	stroke(0);
	fill(c);
	strokeWeight(s / 2);
	let stretch = random(0.7, 1.3);
	beginShape();
	curveVertex(x - stretch * s, y - row * s);
	curveVertex(x - stretch * s, y - row * s);
	curveVertex(x - stretch * s / 2, y + row * s / 1.5);
	curveVertex(x, y + row * s);
	curveVertex(x + stretch * s / 2, y + row * s / 1.5);
	curveVertex(x + stretch * s, y - row * s);
	curveVertex(x + stretch * s, y - row * s);
	endShape();
	line(x - stretch * s, y - row * s, x + stretch * s, y - row * s)
}

// === Tab: Jaw ===
function drawJaw(x, y, sz, c) {
	stroke(0, 200);
	strokeWeight(sz / 20);
	noFill();
	fill(c);
	let stretch = random(-0.2, 0);

	beginShape();
	curveVertex(x - 1.2 * sz, y - 0.25 * sz);
	curveVertex(x - 1.2 * sz, y - 0.25 * sz);
	curveVertex(x - 1.1 * sz, y);
	curveVertex(x - 1.3 * sz - stretch * sz, y + 0.5 * sz);
	curveVertex(x - sz, y + sz);

	curveVertex(x - sz, y + 1.3 * sz);
	curveVertex(x - sz - stretch * sz, y + 1.7 * sz);
	curveVertex(x, y + 2.2 * sz);
	curveVertex(x + sz + stretch * sz, y + 1.7 * sz);
	curveVertex(x + sz, y + 1.3 * sz);

	curveVertex(x + sz, y + sz);
	curveVertex(x + 1.3 * sz + stretch * sz, y + 0.5 * sz);
	curveVertex(x + 1.1 * sz, y);
	curveVertex(x + 1.2 * sz, y - 0.25 * sz);
	curveVertex(x + 1.2 * sz, y - 0.25 * sz);
	endShape();

}

// === Tab: Cranium ===
function drawCranium(x, y, sz, c) {
	stroke(0, 200);
	strokeWeight(sz / 20);
	noFill();
	fill(c);
	let stretch = random(0, 0.1);
	beginShape();
	curveVertex(x - sz, y + 0.5 * sz);
	curveVertex(x - sz, y + 0.5 * sz);
	curveVertex(x - 1.35 * sz, y);
	curveVertex(x - (1.2 + stretch) * sz, y - 1.2 * sz);
	curveVertex(x, y - (1.75 + stretch) * sz);
	curveVertex(x + (1.2 + stretch) * sz, y - 1.2 * sz);
	curveVertex(x + 1.35 * sz, y);
	curveVertex(x + sz, y + 0.5 * sz);
	curveVertex(x + sz, y + 0.5 * sz);
	endShape();
}

// === Tab: Eye ===
function drawEye(x, y, s, c, num, deg) {
	push();
	fill(0);
	noStroke();
	translate(x, y);
	rotate(deg);
	ellipse(0, 0, s * 5, s * 4);
	pop();
	//if(floor(random(5))==0) return;
	noStroke();
	if (brightness(window.color(c)) < 80) fill(c);
	else fill(0);
	ellipse(x, y, s, s);

	let c1 = color(200, green(window.color(c)), blue(window.color(c)), 160);
	let angle = 0;
	push();
	translate(x, y);
	for (let i = 0; i < 2 * num; i++) {
		fill(c1);
		push();
		rotate(angle);
		translate(1.25 * s, 0);
		if (i % 3 == 0) {
			ellipse(0, 0, 1.15 * s, s);
			stroke(c1);
			strokeWeight(4);
			line(-0.75 * s, 0, 0.75 * s, 0);
		}
		translate(s, 0);
		noStroke();
		fill(c);
		if (i % 2 == 0) ellipse(0, 0, s / 3, s / 3)
		angle += TWO_PI / (2 * num);
		pop();
	}
	pop();
}

// === Tab: HalfFlower ===
function halfFlower(x, y, s, c, num, deg, rot, lines) {

	push();
	translate(x, y);
	rotate(rot);
	fill(c);
	ellipse(0, 0, 1.35 * s, 1.25 * s);
	let c1 = color(200, green(window.color(c)), blue(window.color(c)), 190);
	let angle = 0;
	for (let i = 0; i <= num; i++) {
		fill(c1);
		push();
		rotate(angle);
		translate(1.25 * s, 0);
		if (i % 2 == 0) {
			ellipse(0, 0, 1.15 * s, s);
			stroke(c1);
			strokeWeight(4);
			if (lines) line(-0.75 * s, 0, 0.75 * s, 0);
		}
		translate(s, 0);
		noStroke();
		fill(c);
		ellipse(0, 0, s / 3, s / 3)
		angle += TWO_PI / (2 * num);
		pop();
	}
	pop();
}

// === Tab: Cross ===
function drawCross(x, y, sz, c) {
	fill(c);
	rectMode(CENTER);
	let roundness = random(0, 0.08);
	rect(x, y, 0.1 * sz, 0.8 * sz, roundness * sz);
	rect(x, y, 0.4 * sz, 0.1 * sz, roundness * sz);
}

// === Tab: TearDrop ===
function tearDrop(x, y, sz, flip, c, ang, stop, mode) {
	push();
	translate(x, y);
	rotate(ang);
	for (let a = 0; a < stop; a += (Math.max(0.001, Math.abs(stop / 6)) || 1)) {
		push();
		let ds = map(a, 0, HALF_PI, 1, sz / 2);;
		rotate(flip * a);
		translate(flip * 2 * ds, 0);
		fill(0, 100, 0, 100);
		stroke(0);
		strokeWeight(sz / 10);
		fill(c);
		if (mode == 'drop') {
			ellipse(0, 0, ds, ds);
			fill('red');
			ellipse(0, 0, ds / 5, ds / 5);
		} else {
			fill(c);
			rectMode(CENTER);
			rect(0, 0, ds, ds);
			fill('red');
			rect(0, 0, ds / 5, ds / 5);
		}
		pop();
	}
	pop();
}

