let xdim, ydim;
let target;
let fade = false;

function setup() {
	createCanvas(windowWidth, windowHeight);
	ydim = height / 3;
	xdim = ydim / 1.5;
	background(0);
	target = createVector(0, 0);
	drawSkulls();
